# CRC glycolysis/lactate-metabolism multi-omics analysis
# Complete reproducibility script for GitHub
#
# Expected project layout:
#   TCGA/                       TCGA expression/survival files
#   GSE221575/                  10x single-cell count folders
#   genesets.v2024.1.Hs.gmt    MSigDB GMT used in the study
#   glycolysis.csv              GeneCards glycolysis gene table
#   all_risk.txt                Generated by the prognostic-model section
#
# All paths are relative to the project root; no author-specific absolute paths are used.
# The script contains bulk transcriptomics, WGCNA, prognostic modeling,
# immune analyses, Seurat/Harmony/kBET, AddModuleScore, Monocle 2, and CellChat.
#

# 使用当前项目目录；不设置空工作目录
library(tidyverse)
library(limma)
library(clusterProfiler)
#整理TCGA数据
exp <- read.table('TCGA/TCGA-COAD.htseq_counts.tsv.gz',
                  header = T,
                  row.names = 1,
                  check.names = F,
                  sep = '\t')
#转换id
#提取ensemble id
exp$Ensembl_ID <- c(Ensembl_ID = str_split(rownames(exp),'[.]', simplify = T)[,1])
exp$Ensembl_ID
#提取symbol id
name <- bitr(exp$Ensembl_ID, 
             fromType = "ENSEMBL",
             toType = "SYMBOL", 
             OrgDb = "org.Hs.eg.db", 
             drop = TRUE)
#匹配id
exp <- right_join(name, exp, by = c("ENSEMBL"="Ensembl_ID"))
exp <- exp[,-1]
#相同symbol id gene表达取均值
exp <- aggregate(.~SYMBOL, FUN = mean, data = exp)
rownames(exp) <- exp[,1]
exp <- exp[,-1]
save(exp,file = 'tcga_coad_count.Rdata')

exp1 <- exp[,substr(colnames(exp),14,16) == '01A']
save(exp1,file = 'tcga_coad_01A_count.Rdata')


###########差异分析##################
#设置对照水平
load('tcga_coad_count.Rdata')
table(substr(colnames(exp),14,16))
group_list <- ifelse(substr(colnames(exp),14,15) < '10','T','N')
group_list <- factor(group_list,levels = c('T','N')) 

#构建分组
design <- model.matrix(~ 0 + group_list)
design
#命名
colnames(design) <- c('T','N')
rownames(design) <- colnames(exp)
#设置对照
contrasts.matrix <- makeContrasts(T-N, levels = design)

fit <- lmFit(exp,design)
fit <- contrasts.fit(fit, contrasts.matrix)
fit <- eBayes(fit)
deg <- topTable(fit,number = Inf)
#标记上下调基因
k1 <- (deg$P.Value < 0.05)&(deg$logFC < -2)
k2 <- (deg$P.Value < 0.05)&(deg$logFC > 2)
deg$change <- ifelse(k1,"DOWN",ifelse(k2,"UP","NO CHANGE"))
table(deg$change)
#火山图
library(ggplot2)
ggplot(deg,aes(x=logFC,y=-1*log10(P.Value)))+
  #加点
  geom_point(aes(col=change),size=2,alpha=0.5)+
  #加颜色
  scale_color_manual(values = c("#0466c8","#0a0908","#e01e37"))+
  #xy轴范围
  xlim(-10,10)+ylim(0,150)+
  theme(title = element_text(size = 18),text = element_text(size=18))+
  theme_bw(base_size = 15)+
  #加标签
  labs(x="log2(Fold Change)",y="-log10(P.Value)")+
  #去背景
  #theme_classic()+
  #加辅助线
  geom_hline(yintercept = -1*log10(0.05),linetype=4,size=0.7)+
  geom_vline(xintercept = c(-2,2),linetype=4,size=0.7) 
dev.off()

deg_gene <- rownames(deg[deg$change !='NO CHANGE',])

save(deg_gene,deg,file = 'deg_res.Rdata')

#WGCNA
library(WGCNA)
##############WGCNA#####################
#打开多线程
enableWGCNAThreads()
#注：样本数量最少要多于15个
#注：输入数据：基因表达矩阵(行为样本，列为基因)
#注：一般使用方差前2000-5000基因进行wgcna，基因太多电脑跑不动，r容易崩掉，不建议直接使用差异基因进行wgcna
#注：输入数据：性状矩阵：必须是数值型特征，如果是分类变量，需转化为0-1矩阵  
#注：一般使用方差前2000-5000基因进行wgcna，基因太多电脑跑不动，r容易崩掉
exp <- exp[order(apply(exp, 1, mad),decreasing = T)[1:5000],]
#数据倒置
exp <- t(exp)
#开始分析
#1、判断数据质量
gsg <- goodSamplesGenes(exp, verbose = 3)
gsg$allOK #结果是TRUE
#2、样本质控
#使用欧氏距离 (dist(dat)) 计算样本间的距离矩阵。
#使用层次聚类方法（平均连接法）构建聚类树。
sampleTree <- hclust(dist(exp),method = 'average')
par(cex = 0.6)
par(mar = c(0,4,2,0))
plot(sampleTree, main = "Sample clustering to detect outliers", 
     sub="", xlab="", cex.lab = 1.5,cex.axis = 1.5, cex.main = 2)
abline(h = 250, col = "red") #根据实际情况而定是否要划线去除离群点
dev.off()
# 如果有异常值就需要去掉
#if(F){
#  clust = cutreeStatic(sampleTree, cutHeight = 140, minSize = 10)
#  table(clust) # 0代表切除的，1代表保留的
#  keepSamples = (clust!=0)
#  exp1 = exp[keepSamples, ]
#}
# cutHeight = 200:用于指定在层次聚类树中切割的高度。在树状结构中，高度表示样本之间的相似性或距离。
# 通过指定 cutHeight，你可以控制在哪个高度水平切割树，从而确定最终的簇数。
# minSize = 10：用于指定最小簇的大小。在进行切割时，如果某个簇的大小小于 minSize，
# 则可能会合并到其他簇中，以确保生成的簇都具有足够的样本数。
# 切除完了之后需要再回到上面的代码进行做图！
#去除了异常样本之后需要跟临床信息做一个对应
#s <- intersect(rownames(exp),rownames(clinical))
#clinical <- clinical[s,]
#exp <- exp[s,]
#a <- identical(rownames(exp),rownames(clinical))
#没有异常样本就不需要去除
exp1 <- exp
#3、添加表型矩阵联合
#这里要注意的是，用于关联分析的性状必须是数值型特征（比如年龄、体重、基因表达水平等）。
#如果是分类变量（比如性别、地区等），则需要转换为0-1矩阵的形式
#（1表示属于此组或有此属性，0表示不属于此组或无此属性）。
traitData <- data.frame(group_list)
datTraits <- data.frame(
  Tumor = as.numeric(grepl("T", traitData$group_list)),
  Normal = as.numeric(grepl("N", traitData$group_list))
)
#表型和样本的相关性
sampleTree2 <- hclust(dist(exp1), method = "average")
# 用颜色表示表型在各个样本的表现: 白色表示低，红色为高，灰色为缺失
traitColors <- numbers2colors(datTraits, signed = FALSE)
# 把样本聚类和表型热图绘制在一起
#pdf('样本聚类.pdf',width = 15,height = 4)
plotDendroAndColors(sampleTree2, traitColors,
                    groupLabels = names(datTraits),
                    main = "Sample dendrogram and trait heatmap")
dev.off()

#4、软阈值筛选
#设置间隔
powers <- c(c(1:10), seq(from= 12, to = 30, by = 2))
sft <- pickSoftThreshold(exp1, powerVector = powers, verbose = 5)
# pickSoftThreshold 函数的输出，用于选择最佳的软阈值以构建基因共表达网络或网络模型。
# powerEstimate：这是估计的最佳软阈值的值，它是一个整数。在这个结果中，估计的最佳软阈值是6。
# fitIndices：这是一个数据框，包含了不同软阈值下的拟合指标。每一行代表一个不同的软阈值（在 powers 中定义），列包括以下信息：
# Power：软阈值的幂次。
# SFT.R.sq：Scale Free Topology Model Fit，表示拟合模型的拟合度，通常用 R^2 衡量。较高的值表示模型更好地拟合数据。
# slope：表示软阈值幂次与拟合模型的斜率，通常用于衡量网络的无标度拓扑结构。一般来说，斜率绝对值越小，模型越能保持无标度拓扑结构。
# truncated.R.sq：表示截断模型的拟合度，也是一个衡量模型拟合程度的指标。
# mean.k.：平均连接度（Mean Connectivity），用于描述网络中节点的连接性。
# median.k.：中位数连接度，是平均连接度的中位数。
# max.k.：最大连接度，表示网络中具有最多连接的节点的连接数。
#画图，确定阈值
#这里筛选power值，大概意思就是分的每个模块中基因的相关性值，一般情况选阈值（R^2）大于0.85，有斜率变化的数值为选定的power值
pdf('power.pdf',width = 10,height = 5)
par(mfrow = c(1,2))
plot(sft$fitIndices[,1],
     -sign(sft$fitIndices[,3])*sft$fitIndices[,2],
     xlab = "Soft Threshold (power)",
     ylab = "Scale Free Topology Model Fit,sign R^2", type = "n",main = paste("Scale independence"))
text(sft$fitIndices[,1],
     -sign(sft$fitIndices[,3])*sft$fitIndices[,2],
     labels = powers,
     cex = 0.95,
     col = "red")
abline(h = 0.8, col = "red")

plot(sft$fitIndices[,1],
     sft$fitIndices[,5],
     xlab = "Soft Threshold (power)",
     ylab = "Mean Connectivity",
     type = "n",
     main = paste("Mean connectivity"))
text(sft$fitIndices[,1],
     sft$fitIndices[,5],
     labels = powers,
     cex = 0.95,
     col = "red")
dev.off()
#4、构建共表达网络
#这里我们选择power=6来进行后续分析
net <- blockwiseModules(exp1,
                        power = 6, 
                        maxBlockSize = 5000, #模块检测的最大块大小
                        TOMType = 'unsigned', 
                        minModuleSize = 100, #模块检测的最小块大小
                        reassignThresholdPS = 0, 
                        mergeCutHeight = 0.25,
                        numericLabels = TRUE,
                        pamRespectsDendro = FALSE,
                        saveTOMS = TRUE,
                        saveTOMFileBase = 'drought',
                        verbose = 3)
# deepSplit 参数调整划分模块的敏感度，值越大，越敏感，得到的模块就越多；
# minModuleSize 参数设置最小模块的基因数，值越小，小的模块就会被保留下来；
# mergeCutHeight 设置合并相似性模块的距离，值越小，就越不容易被合并，保留下来的模块就越多。
# power = sft$powerEstimate：这里指定了软阈值的取值。
# sft$powerEstimate 就是我们之前计算得到的软阈值，它用来控制共表达网络的连接强度。
# maxBlockSize = nGenes：指定了最大的模块大小。在构建基因模块时，会将基因分成多个子模块，这个参数用来限制子模块的最大大小。
# nGenes 是基因的总数，通常用来作为最大模块大小的上限。（4G内存电脑可处理8000-10000个，16G内存电脑可以处理2万个，32G内存电脑可以处理3万个，计算资源允许的情况下最好放在一个block里面。）
# TOMType = "unsigned"：指定了共表达网络的类型，这里设置为 "unsigned"，表示构建无符号的网络。计算TOM矩阵时，是否考虑正负相关性，默认为"signed"，但是根据幂律转换的邻接矩阵(权重)的非负性，所以我们认为这里选择"signed"也没有太多的意义。
# minModuleSize = 30：指定了每个模块的最小大小，也就是每个基因模块中至少包含多少个基因。
# reassignThreshold = 0：控制模块的重新分配。如果模块中的基因与其他模块的相关性低于这个阈值，它们可能会被重新分配到其他模块。
# mergeCutHeight = 0.25：用来合并基因模块。当两个模块的相关性超过这个阈值时，它们可能会被合并成一个更大的模块。越大得到的模块就越少。
# numericLabels = TRUE：表示模块将使用数值标签，返回数字而不是颜色作为模块的名字，后面可以再转换为颜色。
# pamRespectsDendro = FALSE：控制 PAM（Partitioning Around Medoids）聚类算法是否遵循树状结构。这里设置为 FALSE，表示不遵循树状结构。
# saveTOMs = F：用来控制是否保存共表达网络的拓扑重叠矩阵（TOM）。这里设置为 FALSE，表示不保存。最耗费时间的计算，有需要的话，大家存储起来，供后续使用。
# verbose = 3：用来控制输出的详细程度。设置为3可以输出较为详细的信息，用于跟踪函数的执行进程。
# corType：用来选择计算相关性的方法。默认“pearson”，还可以是“bicor”，“bicor”更能考虑离群点的影响bicor。
table(net$colors)
#6、绘制基因聚类和模块颜色组合
moduleLabels <- net$colors
moduleColors <- labels2colors(moduleLabels)
pdf('dendrogram.pdf',width = 8,height = 4)
plotDendroAndColors(net$dendrograms[[1]],
                    moduleColors[net$blockGenes[[1]]],
                    'Module colors', 
                    dendroLabels = FALSE, #树状图标签
                    hang = 0.03, #线条粗细
                    addGuide = TRUE, 
                    guideHang = 0.05) #添加引导线
dev.off()
#7、合并模块
#计算每个模块的特征向量基因，为某一特定模块第一主成分基因E。代表了该模块内基因表达的整体水平
MEList <- moduleEigengenes(exp1, colors = moduleColors)
MEs <- MEList$eigengenes
# 计算根据模块特征向量基因计算模块相异度：
MEDiss <- 1-cor(MEs)
# Cluster module eigengenes
METree <- hclust(as.dist(MEDiss), method = "average")
#特征向量基因临近热图：
pdf('EigengeneNetworks.pdf',width = 8,height = 5)
plotEigengeneNetworks(MEs, 
                      "Eigengene adjacency heatmap", 
                      marHeatmap = c(3,4,2,2), 
                      plotDendrograms = FALSE, 
                      xLabelsAngle = 90)
dev.off()
#特征向量基因聚类树状图，红线以下的模块表示相关性>0.9，将被合并
plot(METree, 
     main = "Clustering of module eigengenes",
     xlab = "", 
     sub = "")
# 在聚类图中画出剪切线
abline(h=0.1, col = "red")
dev.off()
#8、 相关性系数大于0.9的模块合并掉，即相异性系数小于0.1
#合并模块：
merge_modules <- mergeCloseModules(exp1, 
                                   moduleColors, 
                                   cutHeight = 0.1, 
                                   verbose = 3)
# 合并后的颜色：
mergedColors <- merge_modules$colors
# 新模块的特征向量基因：
mergedMEs <- merge_modules$newMEs
plotDendroAndColors(net$dendrograms[[1]], 
                    cbind(moduleColors, mergedColors),
                    c("Dynamic Tree Cut", "Merged dynamic"),
                    dendroLabels = FALSE, 
                    hang = 0.03,
                    addGuide = TRUE, 
                    guideHang = 0.05)
dev.off()
#9、获取模块基因
moduleLabels <- merge_modules$colors # 对应多步法里面的mergedColors = merge$colors
moduleColors <- labels2colors(merge_modules$colors)
MEs <- merge_modules$newMEs # 对应多步法里的mergedMEs = merge$newMEs 
#geneTree <- net$dendrograms[[1]] #适用于一步法
g <- merge(as.data.frame(table(net$colors)),
           as.data.frame(table(mergedColors)))
g
genes = list()
for(i in 1:nrow(g)){
  genes[[i]] = names(net$colors)[net$colors==g$Var1[[i]]]
}
names(genes) = g$mergedColors
save(genes,file = "genes.Rdata")
#10、相关性热图 
#得到基因、样本数量
nGenes <- ncol(exp1)
nSamples <- nrow(exp1)
# 用color labels重新计算MEs(Module Eigengenes:模块的第一主成分)
moduleTraitCor <- cor(mergedMEs, datTraits, use = "p") #（这是重点）计算ME和表型相关性
moduleTraitPvalue <- corPvalueStudent(moduleTraitCor, nSamples)
#热图
# 设置热图上的文字（两行数字：第一行是模块与各种表型的相关系数；
# 第二行是p值）
# signif 取有效数字
textMatrix <- paste(signif(moduleTraitCor, 2), "\n(",
                    signif(moduleTraitPvalue, 1), ")", sep = "")
dim(textMatrix) <- dim(moduleTraitCor)
pdf('labeledHeatmap.pdf',width = 5,height = 6)
par(mar = c(8, 8.5, 3, 3))
# 然后对moduleTraitCor画热图
labeledHeatmap(Matrix = moduleTraitCor,
               xLabels = names(datTraits),
               yLabels = names(mergedMEs),
               ySymbols = names(mergedMEs),
               colorLabels = FALSE,
               colors = blueWhiteRed (50),
               textMatrix = textMatrix,
               setStdMargins = FALSE,
               cex.text = 0.5,
               zlim = c(-1,1),
               main = paste("Module-trait relationships"))
dev.off()

wgcna_gene <- c(genes$brown,genes$turquoise,genes$yellow)

intersect(wgcna_gene,deg_gene)

#Msigdb:(https://www.gsea-msigdb.org/gsea/msigdb)
lactic_gene <-read.gmt("genesets.v2024.1.Hs.gmt")
