load('tcga_coad_01A_count.Rdata')
library(survminer)
library(survival)
sur <- read.table('TCGA/TCGA-COAD.survival.tsv',header = T,sep = '\t')
sur <- sur[,c(1,2,4)]
colnames(sur) <- c('sample', 'status','survival_time')
sur_df <- merge(sur,as.data.frame(t(exp1[gene_res,])),by.x = 1,by.y = 0)
sur_df$survival_time <- sur_df$survival_time/365
sur_df <- na.omit(sur_df)

sur_exp <- sur_df
rownames(sur_exp) <- sur_exp$sample
sur_exp <- sur_exp[,-1]
outTab <- data.frame()
AllTab <- data.frame()
sigGenes <- c("survival_time","status" )
for (i in 3:ncol(sur_exp)) {
  cox = coxph(Surv(survival_time, status) ~ sur_exp[ ,i], data = sur_exp)
  coxsummary = summary(cox)
  coxp = coxsummary$coefficients[, "Pr(>|z|)"]
  AllTab = rbind(AllTab,
                 cbind(gene = colnames(sur_exp)[i],
                       HR = coxsummary$conf.int[, "exp(coef)"],
                       HR.95L = coxsummary$conf.int[, "lower .95"],
                       HR.95H = coxsummary$conf.int[, "upper .95"],
                       pvalue = coxp))
  if(coxp < 0.05){
    sigGenes = c(sigGenes, sur_exp[,i])
    outTab = rbind(outTab,
                   cbind(gene = colnames(sur_exp)[i],
                         HR = coxsummary$conf.int[, "exp(coef)"],
                         HR.95L = coxsummary$conf.int[, "lower .95"],
                         HR.95H = coxsummary$conf.int[, "upper .95"],
                         pvalue = coxp))
  }
}
