#森林图可视化
#单因素森林图
bioforest <- function(coxfile , forestfile , forestcol ){
  gene <- coxfile$gene
  hr <- sprintf("%.3f", as.numeric(coxfile$"HR"))
  hrlow <- sprintf("%.3f", as.numeric(coxfile$"HR.95L"))
  hrhigh <- sprintf("%.3f", as.numeric(coxfile$"HR.95H"))
  Hazard_radio <- paste0(hr, "(",hrlow, "-", hrhigh, ")")
  pval <- ifelse(coxfile$pvalue < 0.001, "<0.001", sprintf("%.3f", as.numeric(coxfile$pvalue)))
  
  #输出图形
  pdf(file = forestfile, width = 10, height = 4)
  n <- nrow(coxfile)
  nrow <- n+1
  ylim <- c(1, nrow)
  layout(matrix(c(1, 2), nc = 2), width = c(3, 2.5))
  
  #绘制森林图左边的临床信息
  xlim = c(0,3)
  par(mar = c(4, 2.5, 2, 1))
  plot(1, xlim = xlim, ylim = ylim, type = "n", axes = F, xlab = "", ylab = "")
  text.cex = 0.8
  text(0, n:1, coxfile$gene, adj = 0, cex = text.cex)
  text(1.5, n:1, pval, adj = 1, cex = text.cex)
  text(1.5, n+1,'pvalue', adj = 1, cex = text.cex, font = 2)
  text(3.12, n:1, Hazard_radio, adj = 1, cex = text.cex)
  text(3.12, n+1, 'Hazard_radio', adj = 1, cex = text.cex, font = 2)
  
  #绘制森林图
  par(mar = c(4, 1, 2, 1), mgp = c(2, 0.5, 0))
  xlim = c(0, max(as.numeric(hrlow), as.numeric(hrhigh)*1.5))
  plot(1, xlim = xlim, ylim = ylim, type = 'n', axes = F, ylab = "", xaxs = "i", xlab = "Hazard ratio")
  arrows(as.numeric(hrlow), n:1, as.numeric(hrhigh), n:1, angle = 90, code =3, length = 0.05, col = "darkblue", lwd = 2.5)
  abline(v = 1, col = "black", lty = 2, lwd = 2)
  boxcolor = ifelse(as.numeric(hr) > 1, forestcol[1], forestcol[2])
  points(as.numeric(hr), n:1, pch = 15, col = boxcolor, cex = 1.6)
  axis(1)
  dev.off()
  
}
bioforest(coxfile = outTab,  #输出单因素cox的结果文件
          forestfile = 'sig_forest.pdf',  #输入导出图的目录及名字
          forestcol = c('red', 'green')) #输入boxplot的颜色

#########构建模型##########
load("Uni_cox_res.Rdata")
all_exp <- uni_cox_res
library(caret)
library(glmnet)
library(timeROC)
#对分组进行循环，找出train和test都显著的分组
for (i in 1:10000) {
  #数据分组
  set.seed(123)
  intrain <- createDataPartition(y = all_exp[, 3], p = 0.5, list = F)
  train <- all_exp[intrain, ]
  test <- all_exp[-intrain, ]
  trainout <- cbind(id = rownames(train), train)
  testout <- cbind(id = rownames(test), test)
  
  #lasso回归
  x <- as.matrix(train[, c(3: ncol(train))])
  y <- data.matrix(Surv(train$survival_time, train$status))
  set.seed(1234)
  fit <- glmnet(x, y, family = 'cox', maxit = 1000)
  set.seed(12)
  cvfit <- cv.glmnet(x, y, family = 'cox', maxit = 1000, nfolds = 10)
  #lambda.1se或lambda.min获取筛选后的基因，进行构建，lambda.1se获得基因较少，lambda.min获得基因较多，具体情况具体分析
  coef <- coef(fit, s = cvfit$lambda.min)
  index <- which(coef != 0)
  actcoef <- coef[index]
  lassogene <- rownames(coef)[index]
  genecoef <- cbind(Gene = lassogene, Coef = actcoef)
  if(nrow(genecoef) < 2){next}
  
  #输出train风险值
  train_final_gene_exp <- train[, lassogene]
  train_score <- predict(cvfit, newx = as.matrix(train[, c(3: ncol(train))]), s = 'lambda.min', type = 'response')
  outcol <- c('survival_time', 'status', lassogene)
  train <- cbind(train[, outcol], riskscore = as.vector(train_score))
  train_best_threshold_surv <- surv_cutpoint(train,
                                             time = 'survival_time',
                                             event = 'status',
                                             variables = 'riskscore',
                                             minprop = 0.3, #最小比例,防止找到的阈值过于极端
                                             progressbar = T)
  #根据找到的最佳阈值对数据进行分组
  train_best_threshold_df <- surv_categorize(train_best_threshold_surv)
  #创建生存对象，包含生存时间和生存状态信息
  train_surv_obj <- Surv(time = train_best_threshold_df$survival_time,event = train_best_threshold_df$status)
  train <- cbind(train, risk = train_best_threshold_df$riskscore)
  train_risk_out <- train
  
  
  #输出test风险值
  test_final_gene_exp <- test[, lassogene]
  test_score <- predict(cvfit, newx = as.matrix(test[, c(3: ncol(test))]), s = 'lambda.min', type = 'response')
  outcol <- c('survival_time', 'status', lassogene)
  test <- cbind(test[, outcol], riskscore = as.vector(test_score))
  test_best_threshold_surv <- surv_cutpoint(test,
                                            time = 'survival_time',
                                            event = 'status',
                                            variables = 'riskscore',
                                            minprop = 0.3, #最小比例,防止找到的阈值过于极端
                                            progressbar = T)
  #根据找到的最佳阈值对数据进行分组
  test_best_threshold_df <- surv_categorize(test_best_threshold_surv)
  #创建生存对象，包含生存时间和生存状态信息
  test_surv_obj <- Surv(time = test_best_threshold_df$survival_time,event = test_best_threshold_df$status)
  test <- cbind(test, risk = test_best_threshold_df$riskscore)
  test_risk_out <- test
  
  #生存差异pvalue
  diff <- survdiff(Surv(survival_time, status) ~ risk, data = train)
  pvalue <- 1-pchisq(diff$chisq, df = 1)
  difftest <- survdiff(Surv(survival_time, status) ~ risk, data = test)
  pvalue_test <- 1-pchisq(difftest$chisq, df = 1)
  
  #ROC曲线下面积
  predictTime <- 1 #预测时间
  roc <- timeROC(T = train$survival_time,
                 delta = train$status,
                 marker = train_score,
                 cause = 1,
                 weighting = 'aalen',
                 times = c(predictTime),
                 ROC = T)
  roc_test <- timeROC(T = test$survival_time,
                      delta = test$status,
                      marker = test_score,
                      cause = 1,
                      weighting = 'aalen',
                      times = c(predictTime),
                      ROC = T)
  
  #设置阈值
  if((pvalue < 0.05) & (roc$AUC[2] > 0.65) & (pvalue_test < 0.05) & (roc_test$AUC[2] > 0.65)){
    #输出分组结果
    write.table(trainout, file = 'train_data.txt', sep = "\t", quote = F, row.names = F)
    write.table(testout, file = 'test_data.txt', sep = "\t", quote = F, row.names = F)
    #lasso图形
    pdf('lambda.pdf')
    plot(fit, xvar = 'lambda', label = T)
    dev.off()
    pdf('cvfit.pdf')
    plot(cvfit)
    abline(v= log(c(cvfit$lambda.1se, cvfit$lambda.1se)), lty = 'dashed')
    dev.off()
    
    #输出模型公式和风险文件
    write.table(genecoef, file = 'gene_coef.txt', sep = "\t", quote = F, row.names = F)
    write.table(train_risk_out, file = 'train_risk.txt', sep = "\t", quote = F, row.names = T)
    write.table(test_risk_out, file = 'test_risk.txt', sep = "\t", quote = F, row.names = T)
    
    #所有样本风险值
    all_risk_out <- rbind(train_risk_out, test_risk_out)
    write.table(all_risk_out, file = 'all_risk.txt', sep = "\t", quote = F, row.names = T)
    break
  }
}

#生存曲线
#定义生存曲线的函数
biosurvival <- function(inputfile){
  #读取输入文件
  data <- read.table(inputfile, header = T, sep = "\t", check.names = F)
  #比较高低两组之间的生存差异，得到差异基因显著pvalue
  diff <- survdiff(Surv(survival_time, status) ~ risk, data = data)
  #
  pvalue <- 1- pchisq(diff$chisq, df = 1)
  if(pvalue <0.001){
    pvalue <- 'p<0.001'
  }else{
    pvalue <- paste0('p = ', sprintf('%.03f', pvalue))
  }
  fit <- survfit(Surv(survival_time, status) ~ risk, data = data)
  
  #绘制生存曲线
  survplot <- ggsurvplot(fit,
                         data = data,
                         conf.int = T,
                         pval = pvalue,
                         pval.size = 6,
                         legend.title = 'Risk',
                         legend.labs = c("High", "Low"),
                         xlab = "Time(years)",
                         ylab = "Overall survival",
                         break.time.by = 1,
                         palette = c('red', 'blue'),
                         risk.table = T,
                         risk.table.title = "",
                         risk.table.height = .25)
  
  #输出图形
  pdf(file = paste0(basename(inputfile), "_surv.pdf"), onefile = F, width = 10, height = 8)
  print(survplot)
  dev.off()
}

biosurvival('train_risk.txt')
biosurvival('test_risk.txt')
biosurvival('all_risk.txt')


#ROC
#定义ROC曲线的函数
plot_roc_curve <- function(riskfile){
  #读取风险文件
  risk <- read.table(riskfile, header = T, sep = "\t", check.names = F)
  risk <- risk[, c("survival_time", "status", "riskscore")]
  
  #定义ROC曲线的颜色
  biocol <- c('red', 'orange', 'blue')
  
  #创建pdf文件
  pdf(file = paste0(basename(riskfile), '_ROC.pdf'))
  
  #绘制1,3,5年的ROC曲线
  roc_df <- timeROC(T = risk$survival_time,
                    delta = risk$status,
                    marker = risk$riskscore,
                    cause = 1,
                    weighting = 'marginal',
                    times = seq(1, 10, by = 0.1), 
                    ROC = T)
  plot(roc_df, time = 1, col = biocol[1], title = F, lwd = 2)
  plot(roc_df, time = 3, col = biocol[2], add = T, title = F, lwd = 2)
  plot(roc_df, time = 5, col = biocol[3], add = T, title = F, lwd = 2)
  
  #添加图例
  legend('bottomright',
         c(paste0('AUC at 1 year: ', sprintf("%.03f", roc_df$AUC["t=1"])),
           paste0('AUC at 3 years: ', sprintf("%.03f", roc_df$AUC["t=3"])),
           paste0('AUC at 5 years: ', sprintf("%.03f", roc_df$AUC["t=5"]))),
         col = biocol,
         lwd = 2,
         bty = 'n')
  dev.off()
  return(paste0(basename(riskfile), '_ROC.pdf'))
}

plot_roc_curve('train_risk.txt')
plot_roc_curve('test_risk.txt')
plot_roc_curve('all_risk.txt')


#定义风险曲线的函数
library(pheatmap)
bio_risk_plot <- function(inputfile, project){
  #读取输入文件
  data <- read.table(inputfile, header = T, sep = "\t", check.names = F)
  #根据风险得分进行排序
  data <- data[order(data$riskscore), ]
  
  #绘制风险曲线
  riskclass <- data[,'risk']
  lowlength <- length(riskclass[riskclass == 'low'])
  highlength <- length(riskclass[riskclass == 'high'])
  lowmax <- max(data$riskscore[riskclass == 'low'])
  line <- data[, 'riskscore']
  pdf(file = paste0(project, '_riskscore.pdf'), width = 7, height = 4)
  plot(line, 
       type = 'p',
       pch = 20,
       xlab = "Patients(increasing risk score)",
       ylab = 'Risk score',
       col = c(rep('green', lowlength), rep('red', highlength)))
  abline(h = lowmax, v = lowlength, lty = 2)
  legend('topleft', 
         c('High risk', 'Low risk'), 
         bty = 'n', 
         pch = 19, 
         col = c('red', 'green'), 
         cex = 1.2)
  dev.off()
  
  #绘制生存状态图
  color <- as.vector(data$status)
  color[color == 1] <- 'red'
  color[color == 0] <- 'green'
  pdf(file = paste0(project, '_survstat.pdf'), width = 7, height = 4)
  plot(data$survival_time, 
       pch = 19,
       xlab = "Patients(increasing risk score)",
       ylab = 'Survival time (years)',
       col = color)
  legend('topleft', 
         c('Dead', 'Alive'), 
         bty = 'n',
         pch = 19,
         col = c('red', 'green'),
         cex = 1.2)
  abline(v = lowlength, lty = 2)
  dev.off()
  
  #定义热图注释的颜色
  ann_colors <- list()
  biocol <- c('blue', 'red')
  names(biocol) <- c('low', 'high')
  ann_colors[['risk']] <- biocol
  
  #绘制风险热图
  data <- data[order(data$risk,decreasing = T), ]
  data1 <- data[,c(3:(ncol(data)-2))]
  data1 <- t(data1)
  annotation <- data.frame(risk = data[, ncol(data)])
  rownames(annotation) <- rownames(data)
  pdf(file = paste0(project, '_heatmap.pdf'), width = 7, height = 4)
  pheatmap(data1,
           annotation = annotation,
           annotation_colors = ann_colors,
           cluster_rows = F,
           cluster_cols = F,
           show_colnames = F,
           color = colorRampPalette(c(rep('green',3.5), 'white', rep('red', 3.5)))(50),
           scale = 'row',
           fontsize_col = 3,
           fontsize = 7,
           fontsize_row = 8)
  dev.off()
}

bio_risk_plot('train_risk.txt',project = 'train')
