cli <- read.table('TCGA/TCGA-COAD.GDC_phenotype.tsv.gz',header = T, sep = "\t", check.names = F, fill = TRUE, na.strings = "",quote = "")
cli1 <- cli[,c('submitter_id.samples',
               "pathologic_M" , 
               "pathologic_N", 
               "pathologic_T", 
               "age_at_initial_pathologic_diagnosis",
               "gender.demographic",
               "tumor_stage.diagnoses")]

colnames(cli1) <- c('sample','M','N','T','age','gender','stage')
#整理分型数据
cli1 <- na.omit(cli1)
cli1[cli1$M %in% c('M1a','M1b'),2] <- 'M1'
table(cli1$M)

table(cli1$N)
cli1[cli1$N %in% c('N1a', 'N1b', 'N1c'),3] <- 'N1'
cli1[cli1$N %in% c('N2a','N2b'),3] <- 'N2'

table(cli1$T)
cli1[cli1$T %in% c('T4a', 'T4b'),4] <- 'T4'
cli1[cli1$T %in% c('T1','T2'),4] <- 'T1/2'
cli1[cli1$T %in% c('T3','T4'),4] <- 'T3/4'

table(cli1$stage)
cli1[cli1$stage %in% c('stage ia'),7] <- 'Stage I'
cli1[cli1$stage %in% c('stage iia','stage iib','stage iic'),7] <- 'Stage II'
cli1[cli1$stage %in% c('stage iiia', 'stage iiib','stage iiic'),7] <- 'Stage III'
cli1[cli1$stage %in% c('stage iva', 'stage ivb'),7] <- 'Stage IV'
table(cli1$gender)
cli1$gender <- recode(cli1$gender, 'male' = 'Male', 'female' = 'Female')
cli1$stage <- toupper(cli1$stage)
cli1$stage <- sub('STAGE', "", cli1$stage)
cli1$stage <- sub("[A-E]", "", cli1$stage)
cli1 <- cli1[!grepl("NOT", cli1$stage), ]
cli1 <- cli1[!grepl("Tis", cli1$T), ]
cli1 <- cli1[!grepl("MX", cli1$M), ]

