#生存
load('Uni_cox_res.Rdata')
sur_df <- uni_cox_res[,c("survival_time","status","SLC4A4","NTRK2","PPARGC1A","TPM2")]

sur <- merge(sur_df,cli1,by.x = 0,by.y = 1)

rownames(sur) <- sur$Row.names
sur <- sur[,-1]
table(sur$M)
table(sur$N)
table(sur$T)
table(sur$stage)
library(survminer)
library(survival)

#M0
sur1 <- sur[sur$M == 'M0',]
for (i in 3:6) {
  sur1$group <- ifelse(sur1[,i]>median(sur1[,i]),'high','low')
  diff <- survdiff(Surv(survival_time, status) ~ group, data = sur1)
  #
  pvalue <- 1- pchisq(diff$chisq, df = 1)
  if(pvalue <0.001){
    pvalue <- 'p<0.001'
  }else{
    pvalue <- paste0('p = ', sprintf('%.03f', pvalue))
  }
  fit <- survfit(Surv(survival_time, status) ~ group, data = sur1)
  
  #绘制生存曲线
  survplot <- ggsurvplot(fit,
                         data = sur1,
                         conf.int = T,
                         pval = pvalue,
                         pval.size = 6,
                         legend.title = 'Risk',
                         legend.labs = c("High", "Low"),
                         xlab = "Time(years)",
                         ylab = "Overall survival",
                         break.time.by = 1,
                         palette = c('red', 'blue'),
                         risk.table = T,
                         risk.table.title = "",
                         risk.table.height = .25)
  
  #输出图形
  pdf(file = paste0('M0-',colnames(sur1)[i], "_surv.pdf"), onefile = F, width = 10, height = 8)
  print(survplot)
  dev.off()
}


