# 获取数据文件夹下的所有样本文件列表
samples <- list.dirs(SC_DATA_DIR, recursive = FALSE, full.names = FALSE)
# 创建一个空的列表来存储Seurat对象
seurat_list <- list()
# 读取每个样本的10x数据并创建Seurat对象
for (sample in samples) {
  # 拼接文件路径
  data.path <- file.path(SC_DATA_DIR, sample)
  # 读取10x数据，data.dir参数指定存放文件的路径
  seurat_data <- Read10X(data.dir = data.path)
  # 创建Seurat对象，并指定项目名称为样本文件名
  seurat_obj <- CreateSeuratObject(counts = seurat_data,
                                   project = sample,
                                   min.features = 200,
                                   min.cells = 3)
  # 将Seurat对象添加到列表中
  seurat_list <- append(seurat_list, seurat_obj)
}
# 打印所有的Seurat对象列表
seurat_list
# 合并Seurat对象，将所有Seurat对象合并到一个对象中
seurat_combined <- merge(seurat_list[[1]], 
                         y = seurat_list[-1],
                         add.cell.ids = samples)
