################ 单细胞乳酸代谢相关转录评分 ############
# 与原始分析保持一致：直接读取本研究使用的 genesets.v2024.1.Hs.gmt，
# 将该GMT文件中包含的全部基因去重后作为评分基因集合。
# 不再额外按基因集名称筛选LACTATE/LACTIC条目。
library(clusterProfiler)
gmt_all <- read.gmt("genesets.v2024.1.Hs.gmt")
if (!all(c("term", "gene") %in% colnames(gmt_all))) {
  colnames(gmt_all)[1:2] <- c("term", "gene")
}

lactate_genes <- unique(gmt_all$gene)
LRG_genes <- intersect(lactate_genes, rownames(mydata2))

if (length(LRG_genes) < 2) {
  stop("可用于AddModuleScore的基因过少，请核对GMT文件、基因符号及Seurat对象。")
}

write.table(
  LRG_genes,
  file = "single_cell_GMT_gene_set_used.txt",
  quote = FALSE,
  row.names = FALSE,
  col.names = FALSE
)

set.seed(2)
sce_score <- AddModuleScore(
  object = mydata2,
  features = list(LRG = LRG_genes),
  ctrl = 100,
  name = "LRG"
)
if (!"LRG1" %in% colnames(sce_score@meta.data)) {
  stop("AddModuleScore未生成预期的LRG1列，请核对Seurat版本。")
}
sce_score$LRG_Score <- sce_score$LRG1
mydata2$LRG_Score <- sce_score$LRG_Score

# 各主要细胞类型两两Wilcoxon检验，并进行BH校正
metadata_lrg <- mydata2@meta.data[, c("labels", "LRG_Score")]
cell_types <- sort(unique(metadata_lrg$labels))
pair_list <- combn(cell_types, 2, simplify = FALSE)
lrg_test <- do.call(
  rbind,
  lapply(pair_list, function(x) {
    d1 <- metadata_lrg$LRG_Score[metadata_lrg$labels == x[1]]
    d2 <- metadata_lrg$LRG_Score[metadata_lrg$labels == x[2]]
    data.frame(
      group1 = x[1],
      group2 = x[2],
      P_value = wilcox.test(d1, d2)$p.value
    )
  })
)
lrg_test$Adj_P_value <- p.adjust(lrg_test$P_value, method = "BH")
write.csv(lrg_test, "LRG_score_pairwise_Wilcoxon_BH.csv", row.names = FALSE)

pdf("AddModuleScore_celltypes.pdf", width = 9, height = 6)
print(
  ggplot(metadata_lrg, aes(x = labels, y = LRG_Score, fill = labels)) +
    geom_boxplot(outlier.size = 0.4) +
    theme_classic() +
    labs(x = NULL, y = "Lactate metabolism-related transcriptional score") +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1),
      legend.position = "none"
    )
)
dev.off()

pdf("AddModuleScore_tSNE.pdf", width = 8, height = 6)
print(
  FeaturePlot(
    mydata2,
    features = "LRG_Score",
    reduction = "tsne"
  )
)
dev.off()


