#BiocManager::install("monocle")
library(Seurat)
library(monocle)
library(dplyr)
rm(list = ls())
load("sce.RData")
pbmc <-sce
exprs <- as(as.matrix(pbmc@assays$RNA$counts), 'sparseMatrix')
featureData <- data.frame(gene_short_name = row.names(pbmc),row.names = row.names(pbmc))               
fd <- new('AnnotatedDataFrame', data = featureData)
phenoData <- pbmc@meta.data
phenoData$subcell <- pbmc@active.ident
pd <- new('AnnotatedDataFrame', data = phenoData)
cds <- newCellDataSet(exprs,
                      phenoData = pd, 
                      featureData = fd,
                      lowerDetectionLimit = 0.5,
                      expressionFamily = negbinomial.size())

# 用于估算每个细胞的大小因子,目的是归一化基因表达数据以纠正测序深度的差异
cds <- estimateSizeFactors(cds)
# 估算基因表达的离散度，帮助识别高变异的基因，用于差异基因分析和排序
cds <- estimateDispersions(cds)
cds <- detectGenes(cds, min_expr = 0.1)
# 差异基因分析（寻找拟时差异基因）
expressed_genes <- row.names(subset(fData(cds),
                                    num_cells_expressed >= 10))
diff <- differentialGeneTest(cds[expressed_genes,],
                             fullModelFormulaStr="~subcell+orig.ident",
                             reducedModelFormulaStr = " ~ orig.ident",
                             cores=1) #差异基因(速度慢)

# 筛选用于排序的基因
ordergene <- rownames(subset(diff, qval < 0.01)) 
cds <- setOrderingFilter(cds, ordergene)
plot_ordering_genes(cds)

# 设置用于排序的基因
cds <- reduceDimension(
  cds,
  reduction_method = "DDRTree",
  max_components = 2,
  residualModelFormulaStr = "~orig.ident"
)

# 未人为指定root_state，以避免在缺乏额外谱系证据时强加方向性解释。
# 如需明确生物学方向，应根据预先定义且可重复的root选择规则重新orderCells。
cds <- orderCells(cds)
write.csv(
  as.data.frame.matrix(table(pData(cds)$State, pData(cds)$subcell)),
  "Monocle_State_by_subcell.csv"
)
library(ggsci)
p1 = plot_cell_trajectory(cds)+ scale_color_nejm() 
p1 #表示了细胞从一个状态到另一个状态的转变过程
p2 = plot_cell_trajectory(cds, color_by = 'Pseudotime') 
p2 #伪时间（Pseudotime）图，可能代表细胞分化过程
p3 = plot_cell_trajectory(cds, color_by = 'subcell')  + scale_color_npg()
p3 #细胞轨迹图根据细胞类型着色
library(patchwork)
p2+p1/p3
##差异基因绘图
gene_to_cluster = diff %>% arrange(qval) %>% head(50) %>% pull(gene_short_name);head(gene_to_cluster)
p <- plot_pseudotime_heatmap(cds[gene_to_cluster,],
                             num_clusters = nlevels(Idents(pbmc)),
                             show_rownames = TRUE,
                             cores = 4,return_heatmap = TRUE,
                             hmcols = colorRampPalette(c("navy", "white", "firebrick3"))(100))
p


