################ Figure 10F：上皮亚群相关配体-受体互作 ################
epi_lr <- cellchat_all[
  cellchat_all$source %in% epi_groups |
    cellchat_all$target %in% epi_groups,
  ,
  drop = FALSE
]
if ("pval" %in% colnames(epi_lr)) {
  epi_lr <- epi_lr[
    !is.na(epi_lr$pval) & epi_lr$pval < 0.05,
    ,
    drop = FALSE
  ]
}

if (nrow(epi_lr) > 0) {
  if ("interaction_name_2" %in% colnames(epi_lr)) {
    epi_lr$LR_pair <- epi_lr$interaction_name_2
  } else if ("interaction_name" %in% colnames(epi_lr)) {
    epi_lr$LR_pair <- epi_lr$interaction_name
  } else {
    epi_lr$LR_pair <- paste(epi_lr$ligand, epi_lr$receptor, sep = "–")
  }

  epi_lr$Direction <- paste(epi_lr$source, epi_lr$target, sep = " → ")
  if (!"prob" %in% colnames(epi_lr)) {
    stop("CellChat通信表中缺少prob列，无法绘制Figure 10F。")
  }

  if ("pval" %in% colnames(epi_lr)) {
    epi_lr$Significance <- -log10(pmax(epi_lr$pval, 1e-300))
  } else {
    epi_lr$Significance <- 1
  }

  epi_lr <- epi_lr[
    order(epi_lr$prob, decreasing = TRUE),
    ,
    drop = FALSE
  ]

  # 单独导出正文涉及的关键互作，供人工核对，不人为制造不存在的结果
  key_pattern <- "LGALS9|CD44|MDK|NCL|LAMA3|HLA|CD8"
  key_lr <- epi_lr[
    grepl(key_pattern, epi_lr$LR_pair, ignore.case = TRUE),
    ,
    drop = FALSE
  ]
  write.csv(
    key_lr,
    file.path(fig10_dir, "Figure10_key_LR_checks.csv"),
    row.names = FALSE
  )

  # 优先纳入正文涉及的关键互作，再补充通信概率最高的其他互作
  epi_lr_plot <- unique(
    rbind(
      key_lr,
      head(epi_lr, 60)
    )
  )
  epi_lr_plot <- head(epi_lr_plot, 60)

  write.csv(
    epi_lr,
    file.path(fig10_dir, "Figure10F_Epithelial_LR_all.csv"),
    row.names = FALSE
  )

  p_fig10f <- ggplot(
    epi_lr_plot,
    aes(
      x = Direction,
      y = LR_pair,
      size = prob,
      color = Significance
    )
  ) +
    geom_point(alpha = 0.85) +
    theme_bw() +
    labs(
      x = NULL,
      y = "Ligand-receptor pair",
      size = "Communication probability",
      color = "-log10(P)"
    ) +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1),
      axis.text.y = element_text(size = 7),
      panel.grid.minor = element_blank()
    )

  ggsave(
    file.path(fig10_dir, "Figure10F_Epithelial_LR_bubble.pdf"),
    p_fig10f,
    width = 12,
    height = max(7, 0.18 * nrow(epi_lr_plot) + 3),
    limitsize = FALSE
  )
} else {
  warning("当前CellChat结果中未筛选到与N-Epi/T-Epi相关的显著配体-受体互作。")
}

