# 自定义统一的ggplot2主题
my_clean_theme <- function() {
  theme_minimal(base_size = 10) +
    theme(
      # 图形背景与网格线
      panel.background = element_blank(),
      panel.grid.major = element_blank(),
      panel.grid.minor = element_blank(),
      # 坐标轴与边框
      axis.line = element_line(color = "black", linewidth = 0.3),
      axis.ticks = element_line(color = "black", linewidth = 0.3),
      # 标题与标签
      plot.title = element_text(hjust = 0.5, face = "bold", size = 10, margin = margin(b = 8)),
      axis.title = element_text(size = 9, color = "black"),
      axis.text = element_text(size = 8, color = "black"),
      axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1),
      # 图例与边距
      legend.position = "bottom",
      legend.key.size = unit(4, "mm"),
      legend.title = element_blank(),
      plot.margin = margin(5, 5, 5, 5)
    )
}
# 创建绘图函数
create_violin <- function(data, score_type, y_label){
  ggplot(data, aes(x = group, y = Value, fill = subtype)) +
    geom_violin(width = 0.8, alpha = 0.7, position = position_dodge(0.8)) +
    geom_boxplot(width = 0.15, position = position_dodge(0.8), fill = "white", outlier.size = 0.8) +
    stat_compare_means(
      aes(group = subtype),
      method = "wilcox.test",
      label = "p.signif",
      symnum.args = list(
        cutpoints = c(0, 0.001, 0.01, 0.05, 1),
        symbols = c("***", "**", "*", "ns")
      )) +
    scale_fill_manual(values = c("#f94144", "#1982c4")) +
    labs(title = score_type, y = y_label, x = "") +
    my_clean_theme()
}

# 筛选并绘制四个评分类型
plots <- lapply(c("StromalScore", "ImmuneScore", "ESTIMATEScore", "TumorPurity"), function(score){
  df_sub <- filter(df_long, ScoreType == score)  # 按评分类型筛选数据
  
  # 特殊处理 TumorPurity 的 y 轴显示
  if(score == "TumorPurity"){
    y_limit <- c(0, 1)
    y_breaks <- seq(0, 1, 0.2)
  } else {
    y_limit <- range(df_sub$Value) * 1.2  # 自动扩展10%范围
    y_breaks <- scales::pretty_breaks(n = 5)(df_sub$Value)
  }
  
  create_violin(df_sub, score, "Score Value") +
    scale_y_continuous(
      limits = y_limit,
      breaks = y_breaks
    )
})

