# ---- 5. 临床变量清洗函数 ----
clean_gender <- function(x){
  
  x <- tolower(
    trimws(
      as.character(x)
    )
  )
  
  result <- ifelse(
    x == "female",
    "Female",
    ifelse(
      x == "male",
      "Male",
      NA
    )
  )
  
  factor(
    result,
    levels = c(
      "Female",
      "Male"
    )
  )
  
}


clean_race <- function(x){
  
  x <- tolower(
    trimws(
      as.character(x)
    )
  )
  
  result <- ifelse(
    x == "white",
    "White",
    
    ifelse(
      x == "black or african american",
      "Black",
      
      ifelse(
        x == "asian",
        "Asian",
        NA
      )
    )
  )
  
  factor(
    result,
    levels = c(
      "White",
      "Black",
      "Asian"
    )
  )
  
}


clean_T <- function(x){
  
  x <- toupper(
    trimws(
      as.character(x)
    )
  )
  
  result <- ifelse(
    grepl("^T1", x),
    "T1",
    
    ifelse(
      grepl("^T2", x),
      "T2",
      
      ifelse(
        grepl("^T3", x),
        "T3",
        
        ifelse(
          grepl("^T4", x),
          "T4",
          NA
        )
      )
    )
  )
  
  factor(
    result,
    levels = c(
      "T1",
      "T2",
      "T3",
      "T4"
    )
  )
  
}


clean_N <- function(x){
  
  x <- toupper(
    trimws(
      as.character(x)
    )
  )
  
  result <- ifelse(
    grepl("^N0", x),
    "N0",
    
    ifelse(
      grepl("^N1", x),
      "N1",
      
      ifelse(
        grepl("^N2", x),
        "N2",
        NA
      )
    )
  )
  
  factor(
    result,
    levels = c(
      "N0",
      "N1",
      "N2"
    )
  )
  
}


clean_M <- function(x){
  
  x <- toupper(
    trimws(
      as.character(x)
    )
  )
  
  result <- ifelse(
    grepl("^M0", x),
    "M0",
    
    ifelse(
      grepl("^M1", x),
      "M1",
      NA
    )
  )
  
  factor(
    result,
    levels = c(
      "M0",
      "M1"
    )
  )
  
}


clean_stage <- function(x){
  
  x <- tolower(
    trimws(
      as.character(x)
    )
  )
  
  x <- gsub(
    "\\s+",
    " ",
    x
  )
  
  # 注意必须先IV，再III，再II，再I
  result <- ifelse(
    grepl("^stage iv", x),
    "IV",
    
    ifelse(
      grepl("^stage iii", x),
      "III",
      
      ifelse(
        grepl("^stage ii", x),
        "II",
        
        ifelse(
          grepl("^stage i", x),
          "I",
          NA
        )
      )
    )
  )
  
  factor(
    result,
    levels = c(
      "I",
      "II",
      "III",
      "IV"
    )
  )
  
}


