# ---- 7. 单因素Cox函数 ----
pretty_coef_name <- function(
    coef_name,
    variable
){
  
  if(variable == "age"){
    return("Age")
  }
  
  if(variable == "riskscore"){
    return("Risk score")
  }
  
  if(variable == "gender"){
    
    return(
      gsub(
        "^genderMale$",
        "Gender (male vs female)",
        coef_name
      )
    )
    
  }
  
  if(variable == "race"){
    
    x <- coef_name
    
    x <- gsub(
      "^raceBlack$",
      "Race (Black vs White)",
      x
    )
    
    x <- gsub(
      "^raceAsian$",
      "Race (Asian vs White)",
      x
    )
    
    return(x)
    
  }
  
  if(variable == "T"){
    
    x <- gsub(
      "^T",
      "",
      coef_name
    )
    
    return(
      paste0(
        "T stage ",
        x,
        " vs T1"
      )
    )
    
  }
  
  if(variable == "N"){
    
    x <- gsub(
      "^N",
      "",
      coef_name
    )
    
    return(
      paste0(
        "N stage ",
        x,
        " vs N0"
      )
    )
    
  }
  
  if(variable == "M"){
    
    x <- gsub(
      "^M",
      "",
      coef_name
    )
    
    return(
      paste0(
        "M stage ",
        x,
        " vs M0"
      )
    )
    
  }
  
  if(variable == "stage"){
    
    x <- gsub(
      "^stage",
      "",
      coef_name
    )
    
    return(
      paste0(
        "AJCC stage ",
        x,
        " vs I"
      )
    )
    
  }
  
  coef_name
}


run_univariate_cox <- function(
    variable,
    dataset
){
  
  temp <- dataset[
    ,
    c(
      "survival_time",
      "status",
      variable
    )
  ]
  
  temp <- temp[
    complete.cases(temp),
  ]
  
  if(
    is.factor(
      temp[[variable]]
    )
  ){
    
    temp[[variable]] <-
      droplevels(
        temp[[variable]]
      )
    
    if(
      nlevels(
        temp[[variable]]
      ) < 2
    ){
      
      return(NULL)
      
    }
    
  }
  
  
  form <- as.formula(
    paste0(
      "Surv(survival_time,status) ~ ",
      variable
    )
  )
  
  
  fit <- coxph(
    form,
    data = temp,
    ties = "efron"
  )
  
  
  sm <- summary(fit)
  
  
  coef_names <-
    rownames(
      sm$coefficients
    )
  
  
  result <- data.frame(
    
    Variable =
      variable,
    
    Coefficient =
      coef_names,
    
    Label =
      sapply(
        coef_names,
        pretty_coef_name,
        variable = variable
      ),
    
    HR =
      sm$conf.int[
        ,
        "exp(coef)"
      ],
    
    HR.95L =
      sm$conf.int[
        ,
        "lower .95"
      ],
    
    HR.95H =
      sm$conf.int[
        ,
        "upper .95"
      ],
    
    pvalue =
      sm$coefficients[
        ,
        "Pr(>|z|)"
      ],
    
    N =
      nrow(temp),
    
    Events =
      sum(
        temp$status == 1
      ),
    
    stringsAsFactors = FALSE
    
  )
  
  
  overall_p <-
    as.numeric(
      sm$logtest[
        "pvalue"
      ]
    )
  
  
  global <- data.frame(
    
    Variable =
      variable,
    
    N =
      nrow(temp),
    
    Events =
      sum(
        temp$status == 1
      ),
    
    Overall_P =
      overall_p,
    
    stringsAsFactors = FALSE
    
  )
  
  
  list(
    result = result,
    global = global,
    fit = fit
  )
  
}


