# ---- 9. 通用红绿色森林图函数 ----
plot_forest <- function(
    tab,
    filename,
    title = NULL
){
  
  plot_tab <- tab[
    is.finite(tab$HR) &
      is.finite(tab$HR.95L) &
      is.finite(tab$HR.95H) &
      tab$HR > 0 &
      tab$HR.95L > 0 &
      tab$HR.95H > 0,
  ]
  
  
  if(nrow(plot_tab) == 0){
    
    warning(
      paste(
        "没有可用于绘图的数据：",
        filename
      )
    )
    
    return(
      invisible(NULL)
    )
    
  }
  
  
  variable <-
    plot_tab$Label
  
  
  HRLow <-
    sprintf(
      "%.3f",
      plot_tab$HR.95L
    )
  
  
  HRHigh <-
    sprintf(
      "%.3f",
      plot_tab$HR.95H
    )
  
  
  HR <-
    sprintf(
      "%.3f",
      plot_tab$HR
    )
  
  
  HR95 <- paste0(
    HR,
    " (",
    HRLow,
    "–",
    HRHigh,
    ")"
  )
  
  
  pvalue <- ifelse(
    plot_tab$pvalue < 0.001,
    "<0.001",
    sprintf(
      "%.3f",
      plot_tab$pvalue
    )
  )
  
  
  n <- nrow(plot_tab)
  
  pdf_height <-
    max(
      6,
      0.55 * n + 2
    )
  
  
  pdf(
    filename,
    width = 10,
    height = pdf_height
  )
  
  
  nRow <- n + 1
  
  ylim <- c(
    1,
    nRow
  )
  
  
  layout(
    matrix(
      c(1,2),
      ncol = 2
    ),
    widths = c(
      3.2,
      2
    )
  )
  
  
  # 左侧文字
  
  par(
    mar = c(
      4,
      2.5,
      2,
      1
    )
  )
  
  
  plot(
    0,
    xlim = c(
      0,
      3.4
    ),
    ylim = ylim,
    type = "n",
    axes = FALSE,
    xlab = "",
    ylab = ""
  )
  
  
  if(!is.null(title)){
    
    mtext(
      title,
      side = 3,
      line = 0.5,
      font = 2
    )
    
  }
  
  
  text.cex <- 0.78
  
  
  text(
    0,
    n:1,
    variable,
    adj = 0,
    cex = text.cex
  )
  
  
  text(
    2.0,
    n:1,
    pvalue,
    adj = 1,
    cex = text.cex
  )
  
  
  text(
    2.0,
    n + 1,
    "P value",
    adj = 1,
    cex = text.cex,
    font = 2
  )
  
  
  text(
    3.4,
    n:1,
    HR95,
    adj = 1,
    cex = text.cex
  )
  
  
  text(
    3.4,
    n + 1,
    "HR (95% CI)",
    adj = 1,
    cex = text.cex,
    font = 2
  )
  
  
  # 右侧森林图
  
  par(
    mar = c(
      4,
      1,
      2,
      1
    ),
    mgp = c(
      2,
      0.5,
      0
    )
  )
  
  
  xmax <-
    max(
      plot_tab$HR.95H,
      na.rm = TRUE
    ) * 1.08
  
  
  xmax <-
    max(
      xmax,
      2
    )
  
  
  plot(
    0,
    xlim = c(
      0,
      xmax
    ),
    ylim = ylim,
    type = "n",
    axes = FALSE,
    ylab = "",
    xaxs = "i",
    xlab = "Hazard ratio"
  )
  
  
  # 95% CI：深蓝色
  arrows(
    plot_tab$HR.95L,
    n:1,
    plot_tab$HR.95H,
    n:1,
    angle = 90,
    code = 3,
    length = 0.05,
    col = "darkblue",
    lwd = 2.5
  )
  
  
  # HR=1参考线
  abline(
    v = 1,
    col = "black",
    lty = 2,
    lwd = 2
  )
  
  
  # HR>1 红色；HR<1 绿色
  boxcolor <- ifelse(
    plot_tab$HR > 1,
    "red",
    "green3"
  )
  
  
  points(
    plot_tab$HR,
    n:1,
    pch = 15,
    col = boxcolor,
    cex = 1.3
  )
  
  
  axis(1)
  
  
  dev.off()
  
}


