# ---- 17. Harrell C-index + 95%CI ----
get_cindex <- function(
    fit,
    model_name
){
  
  cc <-
    survival::concordance(
      fit
    )
  
  
  c_index <-
    as.numeric(
      cc$concordance
    )
  
  
  variance <-
    as.numeric(
      cc$var
    )
  
  
  se <-
    sqrt(
      variance
    )
  
  
  lower <-
    max(
      0,
      c_index -
        1.96 * se
    )
  
  
  upper <-
    min(
      1,
      c_index +
        1.96 * se
    )
  
  
  data.frame(
    
    Model =
      model_name,
    
    C_index =
      c_index,
    
    Lower95CI =
      lower,
    
    Upper95CI =
      upper,
    
    SE =
      se,
    
    stringsAsFactors = FALSE
    
  )
  
}


cindex_table <- rbind(
  
  get_cindex(
    fit_clinical,
    "Clinical-only"
  ),
  
  get_cindex(
    fit_risk,
    "Risk-only"
  ),
  
  get_cindex(
    fit_combined,
    "Combined"
  )
  
)


