# ---- 26. 安全导出validate结果 ----
# 避免之前as.data.frame报dimnames错误

export_validate <- function(
    val,
    filename
){
  
  mat <- matrix(
    
    as.numeric(
      val
    ),
    
    nrow =
      nrow(val),
    
    ncol =
      ncol(val),
    
    dimnames =
      dimnames(val)
    
  )
  
  
  out <- data.frame(
    
    Statistic =
      rownames(mat),
    
    stringsAsFactors =
      FALSE,
    
    check.names =
      FALSE
    
  )
  
  
  for(
    j in seq_len(
      ncol(mat)
    )
  ){
    
    nm <-
      colnames(mat)[j]
    
    
    if(
      is.na(nm) ||
      nm == ""
    ){
      
      nm <-
        paste0(
          "V",
          j
        )
      
    }
    
    
    out[[nm]] <-
      mat[
        ,
        j
      ]
    
  }
  
  
  write.csv(
    
    out,
    
    filename,
    
    row.names =
      FALSE
    
  )
  
  
  invisible(out)
  
}


