# ---- 27. 提取bootstrap校正C-index ----
extract_boot_cindex <- function(
    val,
    model_name
){
  
  required_cols <- c(
    "index.orig",
    "optimism",
    "index.corrected"
  )
  
  
  if(
    !all(
      required_cols %in%
      colnames(val)
    )
  ){
    
    stop(
      "validate结果缺少预期列名，请打印val检查。"
    )
    
  }
  
  
  apparent_dxy <-
    val[
      "Dxy",
      "index.orig"
    ]
  
  
  optimism_dxy <-
    val[
      "Dxy",
      "optimism"
    ]
  
  
  corrected_dxy <-
    val[
      "Dxy",
      "index.corrected"
    ]
  
  
  data.frame(
    
    Model =
      model_name,
    
    Apparent_C_index =
      0.5 +
      apparent_dxy / 2,
    
    Optimism =
      optimism_dxy / 2,
    
    Optimism_corrected_C_index =
      0.5 +
      corrected_dxy / 2,
    
    stringsAsFactors =
      FALSE
    
  )
  
}


bootstrap_cindex_table <- rbind(
  
  extract_boot_cindex(
    val_clinical,
    "Clinical-only"
  ),
  
  extract_boot_cindex(
    val_risk,
    "Risk-only"
  ),
  
  extract_boot_cindex(
    val_combined,
    "Combined"
  )
  
)


