# ---- 29. 校准曲线函数 ----
#
# 每个时间点重新fit cph，并显式指定time.inc

run_calibration <- function(
    time_point,
    filename
){
  
  fit_cal <- cph(
    
    Surv(
      survival_time,
      status
    ) ~
      
      age +
      gender +
      stage +
      riskscore,
    
    data =
      model_data,
    
    x =
      TRUE,
    
    y =
      TRUE,
    
    surv =
      TRUE,
    
    time.inc =
      time_point
    
  )
  
  
  set.seed(123)
  
  
  cal <- calibrate(
    
    fit_cal,
    
    cmethod =
      "KM",
    
    method =
      "boot",
    
    u =
      time_point,
    
    m =
      50,
    
    B =
      1000
    
  )
  
  
  pdf(
    
    filename,
    
    width =
      5.5,
    
    height =
      5.5
    
  )
  
  
  plot(
    
    cal,
    
    xlab =
      paste0(
        "Predicted ",
        time_point,
        "-year overall survival"
      ),
    
    ylab =
      paste0(
        "Observed ",
        time_point,
        "-year overall survival"
      ),
    
    subtitles =
      FALSE
    
  )
  
  
  abline(
    0,
    1,
    lty = 2
  )
  
  
  dev.off()
  
  
  invisible(
    cal
  )
  
}


