# ---- TCIA IPS 免疫治疗相关探索 ----
rm(list = ls())

library(data.table)
library(dplyr)
library(tibble)
library(ggpubr)
library(ggsignif)

# TCIA数据文件请放在项目目录下
TCIA <- fread(
  "TCIA-ClinicalData (3).tsv",
  header = TRUE,
  sep = "\t",
  data.table = FALSE
)
#ips_ctla4_neg_pd1_neg 表示对抗 CTLA-4 和抗 PD-1 抗体均无应答；
#ips_ctla4_neg_pd1_pos 表示对抗 CTLA-4 无应答，对 PD-1 应答；
#ips_ctla4_pos_pd1_neg 表示对抗 CTLA-4 应答，对 PD-1 无应答；
#ips_ctla4_pos_pd1_pos 表示对抗 CTLA-4 和抗 PD-1 抗体均应答
TCIA <- TCIA[,c(1,25:28)] %>% column_to_rownames("barcode")
allrisk <- read.table(
  "all_risk.txt",
  header = TRUE,
  sep = "\t",
  row.names = 1,
  check.names = FALSE
)

if (!"risk" %in% colnames(allrisk)) {
  stop("all_risk.txt 中未找到 risk 分组列。")
}

group <- allrisk %>%
  rownames_to_column("sample") %>%
  dplyr::select(sample, risk)

group$sample <- substr(group$sample, 1, 12)
group <- distinct(group, sample, .keep_all = TRUE)
ips <- merge(group,TCIA,by.x=1,by.y=0) %>% column_to_rownames("sample")


##绘图
# 1.IPS-CTLA4(-)/PD-1(-)
nn <- ips[, c(1, 2)]
colnames(nn)[2] <- "nn"
pdf("ips_nn.pdf",width = 6,height = 6)
ggboxplot(nn, 
          x="risk", 
          y="nn",
          xlab = "",
          ylab = "IPS-CTLA4(–)/PD-1(–)",
          color = "risk",
          order=c("high","low"),
          bxp.errorbar=T,
          bxp.errorbar.width = 0.1,
          palette = "lancet", 
          add = "jitter", 
          lwd=0.7, 
          fatten = 2
) +
  scale_color_manual(values = c("#C4403B","#4682B4"))+
  geom_signif(comparisons = list(c("high","low")),
              map_signif_level = T, 
              test = "wilcox.test", 
              y_position = c(11),
              tip_length = c(c(0.05,0.05)),
              size=0.8,color="black")+
  theme(legend.position = "top",
        axis.title.x =element_text(size=14),
        axis.title.y=element_text(size=14),
        axis.text.x=element_text(size=14),
        axis.text.y=element_text(size=14),
        plot.margin = grid::unit(c(2, 2, 2, 2), 'cm'))
dev.off()

