############# 免疫队列IMvigor210CoreBiologies ################
load("IMvigor210CoreBiologies.Rdata")

###提取id和gene symbol列
genes <- annoData[,c("entrez_id","symbol")]

exprSet <- data.frame(expreSet)
exprSet <- merge(exprSet,genes,by.x = 0,by.y = 1)
#处理重复基因
rowMeans = apply(exprSet,1,function(x) mean(as.numeric(x), na.rm = T))####计算行平均值
rowMeans_2 = data.frame(rowMeans)
exprSet = exprSet[order(rowMeans, decreasing = T),] #排序
dim(exprSet)
exprSet_2 = exprSet[!duplicated(exprSet[, dim(exprSet)[2]]),] #去掉重复基因
dim(exprSet_2)
exprSet_na = na.omit(exprSet_2)   #去掉缺失值
explan_final <- exprSet_na[exprSet_na$symbol!= "",]
dim(explan_final)

#处理一个探针对应多个基因
#explan_final <- data.frame(explan_final[-grep("/",explan_final$Symbol),]) #去一对多，grep是包含的意思，-就是不包含
#dim(explan_final)
rownames(explan_final) <- explan_final$symbol
explan_final <- explan_final[,-c(1,ncol(explan_final))]
IMvigor_exp <- explan_final
#临床信息
cl <- phenoData[,c(2,21,22)]
colnames(cl) <- c("response","time","status")
table(cl$response)
IMvigor_clin <- cl
save(IMvigor_exp,IMvigor_clin,file = c('IMvigor_exp_clin.Rdata'))


#验证
load("IMvigor_exp_clin.Rdata")
IMvigor_exp <- IMvigor_exp[rowSums(IMvigor_exp)>0,]
library(limma)
IMvigor_exp <- normalizeBetweenArrays(IMvigor_exp)
IMvigor_exp <- log2(IMvigor_exp+1)

gene <- c("NTRK2","UCHL1","TPM2","STC2","SLC4A4","PPARGC1A")
gse <- IMvigor_exp[which(rownames(IMvigor_exp) %in% gene),] %>% 
  t() %>% 
  as.data.frame()
clin <- IMvigor_clin
gse <- merge(clin,gse,by.x = 0,by.y = 0) %>% 
  column_to_rownames("Row.names")

gse$time <- as.numeric(gse$time)
gse$status <- as.numeric(gse$status)
gse <- na.omit(gse)


multiCox <- coxph(Surv(time, status) ~ NTRK2+UCHL1+TPM2+STC2+SLC4A4+PPARGC1A, data =  gse)#
gse$riskscore=predict(multiCox,type="risk",newdata=gse)# 


data2 <- gse %>% rownames_to_column("sample")
data2 <- data2[, c("sample", "response", "riskscore")]


group=levels(factor(data2$response))
data2$response=factor(data2$response, levels=group)
comp=combn(group,2)
my_comparisons=list()
for(i in 1:ncol(comp)){my_comparisons[[i]]<-comp[,i]}
#绘制boxplot
library(ggpubr)
boxplot=ggboxplot(data2,
                  x="response",
                  y="riskscore",
                  color="response",
                  xlab="",
                  ylab="riskscore",
                  legend.title="",
                  palette = c("#096EA9","#FC5256"),
                  add = "jitter")+ 
  stat_compare_means(comparisons = my_comparisons,method = "wilcox.test")
boxplot


###绘生存曲线图 
gse$risk_group <- as.vector(ifelse(gse$riskscore>median(na.omit(gse$riskscore)),"high","low"))
library(survminer)
surv_TTP<-survfit(Surv(time, status) ~ risk_group, data =gse)
ggsurvplot(surv_TTP,
           pval = TRUE, #计算并显示组间差异的显著性
           conf.int = T, #是否显示置信区间
           risk.table = T, #风险表格，显示对应的患者数量
           xlab = "time",  #x轴的label
           ylab = "Survival Proportion", #y轴的label
           legend.title = "group",
           main = "Survival curves",
           ncensor.plot = TRUE,
           risk.table.y.text.col = T, # risk table文字注释颜色
           risk.table.y.text = FALSE )
